import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

/**
 * The demo seed is generated by the draw engine. The generator checks the
 * scenarios itself (7KQ2 cadrage with the demo team playing, C4DR finished
 * with a cadrage in A, B and C, 2J7P live and on pause) and throws otherwise.
 */
const root = path.resolve(__dirname, "../../..");
const generated = execFileSync(path.join(root, "node_modules/.bin/tsx"), [path.join(__dirname, "generate-seed.ts")], {
  cwd: path.resolve(__dirname, ".."),
  encoding: "utf8",
  maxBuffer: 64 * 1024 * 1024,
});

describe("demo seed (P2)", () => {
  it("is up to date (pnpm seed:gen)", () => {
    expect(generated).toBe(readFileSync(path.join(root, "supabase/seed.sql"), "utf8"));
  });

  it("is pétanque only: FT8S is gone, the football sport stays defined but no tournament uses it", () => {
    expect(generated).not.toContain("FT8S");
    const block = (table: string) => generated.split(`insert into public.${table} `).slice(1).map((s) => s.split(";\n")[0]!).join("");
    for (const table of ["tournaments", "announcements", "clubs"]) expect(block(table), table).not.toContain("'football'");
  });

  it("holds the six demo tournaments", () => {
    for (const code of ["GP3M", "7KQ2", "TR8E", "C4DR", "2J7P", "PQ8P"]) expect(generated).toContain(`'${code}'`);
  });

  it("gives players a club (public number + name)", () => {
    expect(generated).toMatch(/insert into public\.players \([^)]*club_number, club_name/);
    expect(generated).toContain("'0130421', 'AS LES PLATANES'");
  });
});
